";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"Shifting barriers in tech reveal new questions about trust, safety, and sustainability in software.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 22 Oct 2026 14:08:12 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:38;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Open Channels FM: Balancing Digital Life While Making the Internet Weird Again\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564472\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://openchannels.fm/balancing-digital-life-while-making-the-internet-weird-again/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"Bowe Frankema shares how digital creation affects daily life and what bringing weirdness back to the internet means.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 22 Oct 2026 12:08:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:39;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"Open Channels FM: Munich Bets on Open Source as Meta Apple and NVIDIA Drive Local AI and Hardware Choices\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564438\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"https://openchannels.fm/munich-bets-on-open-source-as-meta-apple-and-nvidia-drive-local-ai-and-hardware-choices/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"Munich’s shift to practical open source, Meta and Apple’s AI partnership, and NVIDIA’s hardware-driven open AI models\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:40;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"WordPress.org blog: Critical PHP Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21835\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://wordpress.org/news/2026/10/critical-php-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2398:\"<p class=\"wp-block-paragraph\"><a href=\"https://www.php.net/archive/2026.php#2026-10-21-5\">The PHP project has announced a security release that fixes two critical security vulnerabilities discovered in PHP</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Due to the critical severity of the issues, site owners are encouraged to immediately update their installations of PHP. Your web host may already be working to update PHP and put web application firewall (WAF) rules in place to mitigate the vulnerabilities, but you should still check for updates from your web host and, if necessary, update PHP as soon as possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Within WordPress, you can see which version of PHP your site runs under Tools &gt; Site Health &gt; Info &gt; Server. Many web hosts provide this information in your web hosting administration panel too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These vulnerabilities are <em>not</em> specific to WordPress and affect any server that hosts a PHP application. No WordPress update is required or planned for these issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Versions of PHP prior to 8.2 no longer receive security updates from the PHP project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If your site runs a version prior to this and you manage your own web hosting, you should <em>consider taking your server offline</em> while you prepare to update to a newer version of PHP. This advice is being published by several national cyber security agencies. To quote <a href=\"https://www.ncsc.gov.uk/news/critical-security-issue-affecting-php\">the UK National Cyber Security Centre</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Where immediate remediation is not feasible, organisations should consider taking the system offline until it can be fully mitigated.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Further information on wordpress.org:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/support/update-php/\">Get a faster, more secure website: update PHP today</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/handbook/references/php-compatibility-and-wordpress-versions/\">PHP Compatibility and WordPress Versions</a></li>\n\n\n\n<li><a href=\"https://wordpress.org/documentation/article/faq-my-site-was-hacked/\">FAQ My site was hacked</a></li>\n</ul>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 13:44:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:41;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"WPTavern: #238 – Chris Huber on How Static Site Importer Makes Migrating Any Website to WordPress Easier Than Ever\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209164\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:131:\"https://wptavern.com/podcast/238-chris-huber-on-how-static-site-importer-makes-migrating-any-website-to-wordpress-easier-than-ever/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:48687:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, how the Static Site Importer makes migrating any website to WordPress easier than ever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Chris Huber. Chris&#8217;s journey with WordPress began in his college days, first as a writer and blogger, and eventually progressing to software engineering after moving his personal site, extrachill.com to WordPress in 2018, Chris went deeply into WordPress, developing custom plugins and exploring all the corners of the platform. His passion for experimentation and creative tech led him to Automattic where he now helps shape the WordPress experience as a software engineer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our discussion centres around two main topics, Data Liberation and the Static Site Importer tool.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We focus upon the evolving landscape of website migration and ownership. Chris explains how Data Liberation aims to make it easier for users to take control of their sites, whether they&#8217;re moving to WordPress from platforms like Wix, Squarespace, or Drupal, or just want portability for their data.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into the Static Site Importer, which takes this a step further by converting any static HTML / CSS website into a fully editable WordPress block theme, headers, footers, and all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris walks us through how these tools work in tandem, highlighting the mechanics behind website crawling, mapping HTML elements to Gutenberg blocks, and handling complex features like WooCommerce and calendars.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the continuous improvement of these tools, how each migration helps raise the bar for future imports, and how this project could fundamentally change the way people move websites between platforms.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re curious about the future of website migration, and how WordPress is removing the hurdles for users who want to truly own and manage their content, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Chris Huber.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Chris Huber. Hello, Chris.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:21] <strong>Chris Huber:</strong> Hey Nathan. Thanks for having me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:22] <strong>Nathan Wrigley:</strong> Yeah, very welcome. Chris and I have never spoken before, but we&#8217;re going to be talking today about two things, data liberation, but also a tool that I&#8217;ve never used, but sounds really interesting. It&#8217;s called the Static Site Importer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As is always the case, if you go to wptavern.com and search for the episode with Chris in it, you&#8217;ll be able to find all of the necessary links. In this case, it&#8217;ll be, GitHub pages and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But before we get stuck into it, Chris, would you mind just telling us a little bit about yourself, your background with WordPress, who you work for, that kind of thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:54] <strong>Chris Huber:</strong> So I&#8217;m Chris. I live in South Carolina. My background with WordPress is I started my own blog back when I was in college, that was 2011. But I wasn&#8217;t on WordPress at the time. I switched to WordPress around 2018, and I started getting more and more into it over the years. Now I work for Automattic as of about six months ago. And I&#8217;m a software engineer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:14] <strong>Nathan Wrigley:</strong> Thank you. So before those six months, a lot of people in the WordPress space have this, I think, desire to end up at a place like Automattic where they can fully work just on WordPress. That&#8217;s my estimation anyway sometimes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:26] <strong>Chris Huber:</strong> Definitely a dream job. I really love working on WordPress, and it&#8217;s super cool to be able to work at Automattic but I got into software engineering a little bit later in my WordPress career. I was more of a writer and a blogger at first, and over time my website started getting more advanced and I wanted to build more things on it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I got, I was an early adopter to AI, and I started learning a lot. Like as soon as I picked up AI, I started asking a lot of questions and turned my website, my personal WordPress site is called extrachill.com, and it&#8217;s kind of a WordPress multi-site like application with 60 custom plugins on it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I just, I just went crazy. That&#8217;s how I ended up at Automattic is because my website, some things I built on my website were like, attention on Twitter from some people who have been around WordPress for a good bit of time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:15] <strong>Nathan Wrigley:</strong> Yeah, I&#8217;ve noticed this trend. I think there&#8217;s a trend in upper management. Let&#8217;s go for that phrase, for the more curious bits. The unusual, the interesting, the weird and the wonderful. I think there&#8217;s a bit of a movement right now to see that again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Back in the day, I have grey hair, I am considerably older than you, I think Chris. And, when the internet began, I was old enough to be able to use a computer. The internet was a truly strange place. Nobody had the faintest idea what to do with it. And so everybody launched their crazy, unusual thing, and it was normal. And then everything became a bit of a homogenised version of the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These social media platforms came along and normalised everything. And UIs settled down and UXs settled down, and got stuck in a rut. But now there does feel, especially in the WordPress space, as if there&#8217;s a desire create the unusual, and the weird and the wonderful, and that&#8217;s brilliant. That sounds like you&#8217;ve been hired to do just that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What we&#8217;re going to talk about today is not that weird. It&#8217;s fairly useful though, I would say. And, there&#8217;s two parts to it. As I mentioned at the top of the show, there&#8217;s the data liberation part, and then there&#8217;s the static sighting importer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think we&#8217;ll go through them in turn, if that&#8217;s all right? Starting with the Data liberation. This was a phrase that I used to trot out a couple of years ago when the Data Liberation project began.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you want to just run and tell us what the Data Liberation Project is, what its goals are?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:42] <strong>Chris Huber:</strong> So the Daily Liberation Project has been ongoing since way before I started working on it. And it is basically, a lot of proprietary website building platforms make it really hard to get off of these platforms. Especially if you want to keep your website design. And that&#8217;s their business model is, they&#8217;re not open source.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So for a long time we have assumed that Data Liberation meant using WordPress. But recently we have changed that definition a little bit, and it just means turning any website into a portable copy that you can download, and do whatever you would like with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the data Liberation Agent that we have created actually can convert any URL into a portable copy. So you just give it a URL and it loads the site in a browser, and downloads every single page as a perfect copy with all the animations and everything. The only thing it doesn&#8217;t get is anything that&#8217;s inside the database, inside the site. Because it&#8217;s all happening on the outside of the site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that&#8217;s step one to our process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:42] <strong>Nathan Wrigley:</strong> I think that&#8217;s great. I remember it being couched in terms of trying to onboard people from going to use the word rival, although that&#8217;s the wrong word, rival CMSs. So for example, Drupal and Joomla and things like that. The idea being that its really hard work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It can be a lot of work getting a site from over there, Drupal, let&#8217;s say, and bringing it over to WordPress. And so there was an endeavour to make it point and clickable. And in, in the way that you&#8217;ve described it, all that you have to do really to get a fairly functional version of your website is to know the URL.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So you go to the original domain, you paste in the URL, some magical voodoo goes on in the background. And within a few moments, that site has been replicated, and hopefully it can then be migrated over to WordPress. But I suppose it goes a little bit further than that because it&#8217;s a two-way promise, isn&#8217;t it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s not just that you can bring things into WordPress. The promise is that should you become fed up of WordPress, you could go in the other direction. You could go WordPress to Drupal. Or indeed you could go WordPress, WordPress. So you could use it as a migration tool or something like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it isn&#8217;t just this importing mechanism, it really is liberation in the strictest sense of the word. It&#8217;s your data. Pick it up from wherever it is now. Take it to wherever the heck you want it to go, and we&#8217;ll enable you to do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:01] <strong>Chris Huber:</strong> Yeah, basically. Not even just Drupal, but places like Wix and Squarespace and Weebly and other website building platforms that might be proprietary and open source. Yeah, that&#8217;s step one to the process that we&#8217;re using.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:13] <strong>Nathan Wrigley:</strong> Okay, is there anything technical that we need to know about how that process works before we move on to the Static Site Importer? Or are the two things bound so that if we move on, it&#8217;ll all make sense in due course.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:24] <strong>Chris Huber:</strong> It will all make sense I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:25] <strong>Nathan Wrigley:</strong> Yeah. I&#8217;ll interrupt as I see fit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the next part of this jigsaw puzzle, now that we&#8217;ve got the data liberation piece under control is the Static Site Importer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, this to me at least is new. I had not seen it. I caught a post by a colleague of yours, on maybe it was X or something like that. And I saw it and I thought, okay, that&#8217;s interesting. Static Site Importer, what does that mean? And I dug a little bit deeper, and that&#8217;s why you are on the podcast to explain it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, 10,000 mile view looking down, what&#8217;s the goal of the project? And then I suppose we can get into how it does it and all of that magical stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:59] <strong>Chris Huber:</strong> So the goal of the project is to create WordPress Block Themes from a static HTML website. So any basic HTML, CSS, JavaScript website, converting it into a WordPress site, with the click of a button. So that&#8217;s the basic goal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:15] <strong>Nathan Wrigley:</strong> Okay, so the idea here is that you see a website somewhere online, hopefully it&#8217;s yours. And then you take the URL, but rather than the sort of more generic approach that we just described with Data Liberation, this is then binding it into, you said theme. I&#8217;m going to go with blocks in my definition here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For example, where there&#8217;s a paragraph. Inside the block editor, we would see a paragraph block. And if it was an image, we&#8217;d see an image block. And I guess if there was something on the left and something on the right, we&#8217;d see a, I don&#8217;t know, a group block or something like that. And the design would trickle down from there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The tool itself would make assumptions based upon what it, I&#8217;m doing air quotes, sees. And then it would build it inside the block editor. But curiously, you said theme, so is it also building a theme in the background to take care of all the other, I don&#8217;t know, the headers and the footers and all of that kind of stuff as well?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:10] <strong>Chris Huber:</strong> Yeah, it is materialising an entire WordPress site from scratch. So the importer does take a URL, but how we&#8217;re using it in our tools is we are combining it with data liberation first.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So data liberation gives us that clean copy of the website. So the URL actually goes through data liberation, and then we take the portable copy created by data liberation, and import the whole entire website into WordPress. And it turns this static website into a WordPress site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s not just about URLs. It&#8217;s also about like AI generated websites that you might have on your computer that you might have generated with Claude or Codex. And you want to use it on WordPress. It&#8217;s traditionally been pretty hard to get a high quality block theme from an AI agent without a lot of iteration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So this kind of sidesteps that need to iterate on the block theme, and pull your hair out with the AI who doesn&#8217;t understand so much about how to create a good block theme. And you just don&#8217;t bother with that, and you just convert it into a block theme on its own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The point of it really is removing the responsibility from the AI to create the block theme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:14] <strong>Nathan Wrigley:</strong> Okay. So the way that you described it, it sounded like, forgive forgive me if I&#8217;ve misunderstood this. It sounded like you use the tool, and we&#8217;ll get into how that works properly in a minute. You use the tool. You paste in a URL, that could be a locally hosted website, or it could be something out in the wild on the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then the data liberation part of it spins up. And then it sounds like there&#8217;s a blob of data somewhere, which the data liberation tool finally exports. So it does its bits. This blob of data is then consumed, and we can discuss what that is. Is that a plugin? How does that even work?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then once it&#8217;s parsed that blob of data, then it can figure out, okay, this part belongs in the header, this part belongs in the footer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This part is the main content area, this is the homepage. And so on. How does it do that? How does it shatter out particular URLs? Like this is the about us page. Or do you have to do it page by page? About, home, archive? How does it do all that? Is it literally one URL and it goes around and spiders the whole thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:13] <strong>Chris Huber:</strong> It crawls every page on the website, the data liberation part does. But I think of the importer almost like a giant funnel and like a sorting mechanism. And it&#8217;s very much mapped to Core, WordPress Core. So I built the whole thing&#8217;s built with AI and just basically like over time mapping different elements on the page to Gutenberg, while having the AI read Gutenberg Core directly, and read the source and make its own mappings.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the whole thing is just a series of import, a website, see what breaks. I pull it up on my screen, side by side. And I&#8217;ll be like, all right, this looks wrong, like this and this. And then you just run it again. And I wrote a prompt basically, an AI orchestration prompt that teaches the AI how to run this loop, like for a long period of time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So how I&#8217;ve built it is I&#8217;ve basically just given the AI a URL, and had multiple sessions going side by side, working on different types of URLs. And they just run, and open pull requests.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The assumption that a lot of people would make about something like this is you take the HTML site and you tell the AI how to build the block theme from it. We&#8217;re not using the AI to do that. We&#8217;re using the AI to improve on the importer. So that every time we run an import, it raises the floor just a little bit. So the more sites that you run through it and loop on it like this, the better quality overall you&#8217;re going to get for just a random, arbitrary website that you might feed it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s really just about data annotation, and taking as much as you can in finding ways to parse it without having to look at it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:41] <strong>Nathan Wrigley:</strong> Does the tool phone home. So the way you described it there was, it sounds like there was an opportunity to improve the tool for yourself on your install. But I was wondering if it phoned home so it also at the same time, improved the tool for everybody else so that the next version of the tool is better for everybody?</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I&#8217;m going to guess that it is just working locally. It&#8217;s improving your version each time. But I could be wrong.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:05] <strong>Chris Huber:</strong> So the prompt I share with my coworkers, and we all use it to work on the tool, so it&#8217;s more of a development thing is how I&#8217;ve built the tool is just by importing a tonne of different websites, over and over again. But the way I have it set up on GitHub is every merge to main automatically releases a new version and updates all the pins.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the latest release is always the latest work that I&#8217;ve done. So, I get to benefit from the changes right away. As soon as I merge the PR, it&#8217;s in a new release and I can just keep going. It&#8217;s just not on wordpress.org yet, or anything like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:37] <strong>Nathan Wrigley:</strong> So how do we actually get hold of the tool? I&#8217;m going to link to a, a GitHub page, but just reading it into the record, it&#8217;s actually a fairly straightforward url. It&#8217;s github.com/automattic. You know the one with the two T&#8217;s, and then static-site-importer. You can go over there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How does it work? You download it. You run it locally on your machine? And then once that&#8217;s up and running, what do you see? Is there like a GUI that you have to run through? Is there a WordPress plugin component to it? Just describe the workflow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:07] <strong>Chris Huber:</strong> Okay. Yeah, so the Static Site importer is a WordPress plugin. And anyone can instal it on a WordPress site to turn a website into a WordPress site for sure. Using the command line locally. It works in the browser too, but there&#8217;s no UI. It&#8217;s like API based, so you&#8217;d have to call the API to do it or the CLI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Another place to use it and the easiest, probably the easiest place for anyone listening, to try it other than Riad&#8217;s website, is WordPress Studio. I added a tool to the CLI in WordPress Studio. That is, studiocreate-from. And then you can enter a URL. So it&#8217;s just one CLI command, and that orchestrates the whole thing in the background. Loads the Data Liberation agent, and then installs Static Site Importer on the site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You run it once you wait 10 or 15 minutes, and it spits out a WordPress Studio site that&#8217;s built using this tool. And that is the same way we run it on wordpress.com. Riad&#8217;s tool, the liberate.sh is a, it uses the wordpress.com API, which works the exact same way as WordPress Studio, where it loads Data Liberation Agent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And Riad&#8217;s website gives you a copy of the website that you can download and take with you, anywhere you want. A WordPress website, anywhere. You can host it anywhere. but it&#8217;s all using the same wordpress.com API on the backend. Except in WordPress Studio uses the actual tools, does that make sense?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:21] <strong>Nathan Wrigley:</strong> Thank you. That&#8217;s great. And so how successful is it? If you point it at google.com, it&#8217;s probably going to a fairly easy time with it because there&#8217;s not a lot going on. But, i&#8217;m imagining on a, let&#8217;s imagine that you went to some high-end sports website or something where they&#8217;ve got animations of people and videos, and all sorts of stuff going on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How does it hold up? For paragraphs and images and all of that kind of stuff? I&#8217;m guessing it&#8217;s pretty good. Are there any areas where you&#8217;d need to be a little bit more mindful? Because, I don&#8217;t know, just experience shows it doesn&#8217;t work out so well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:53] <strong>Chris Huber:</strong> Yeah, definitely. So if you&#8217;re watching it today, there might be some failures on things like stores. Things that have a lot of products and like really image heavy websites might have problems as well. And just like really large websites. But it gets better every single day. What I say right now might become outdated very fast on what we can and can&#8217;t handle, but it definitely is not like perfect yet, for sure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A small website, like a one page brochure website, or five pages or so. Most of the time you&#8217;ll get a pretty good copy of it. If you start to scale up to a really big, large, for example, wix.com, like the actual Wix.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:30] <strong>Nathan Wrigley:</strong> Good luck.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:31] <strong>Chris Huber:</strong> I sometimes will run that through there as a way to see how far I can get. Yeah, I&#8217;m trying to reach for the stars. So eventually I would love to be able to import this 50,000 page heavy duty, old school website, but right now it fails miserably, and it would take. The timing that was given to me last night when I was working on this was like two weeks. You&#8217;ll have a copy of wix.com, if you just let it run. And then you&#8217;d get the copy and it would just be like 10,000 pages of nonsense. We have a lot of work to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:59] <strong>Nathan Wrigley:</strong> Okay, but for a normal, typical, run of the mill, let&#8217;s go with brochure site, 12 pages, fairly ordinary stuff. Imagery, maybe a video here and there, but mostly text, CSS, maybe a tiny smattering of JavaScript sprinkled around. Forms, that kind of thing. It would do a pretty good job with that out of the box?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:17] <strong>Chris Huber:</strong> I would say like more than half the time you would get a good editable WordPress website. Not always perfect. And sometimes you would get a perfect site. But a lot of times you might have a few things that are wrong, like maybe a couple form fields, or like buttons or like menus.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One thing that happens a lot is like the header and the footer are like duplicated across every page, instead of being properly extracted into a template part. If there&#8217;s like SVG images, WordPress has a kind of a hard time handling those. So we have dealt with it. But it&#8217;s not always perfect.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the coolest things about it that I like is that blocks, so it&#8217;s static site importer is the WordPress plugin that creates the WordPress site. And then there&#8217;s a PHP package inside of it called Block Engine. Which is what handles the actual, like, mechanics of converting and creating the blocks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And inside of that tool I have added some like carried blocks that are in the holster ready to go, like for common elements that might appear on websites in the wild.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So like a marquee or something like that. Like a ticker that you see running across a page that Gutenberg cannot represent on its own, out of, the box. And so this tool, it knows how to build this block as if it was part of Gutenberg, so that you&#8217;ll see a real block in there. That&#8217;s my WordPress nerd favourite thing about the tool. It feels like I&#8217;m pushing on Gutenberg, finding places where Gutenberg is like maybe falling short, or just doesn&#8217;t supply the things that people need to build websites. With the right amount of attention, this might help be like, oh, we need to add some of this stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:48] <strong>Nathan Wrigley:</strong> A curious question, because we all know how AI never gives you the same thing twice. I was wondering if you fed it the same URL, do you predictably get something similar out? Or do you suffer each time a different set of, and I&#8217;m doing air quotes again, failures. So for example, you described, the SVG images, or the form fields, or the footers being duplicated or whatever it was.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Is it sometimes better just to begin again, and cross your fingers and hope that the AI has a better go the second time around? Or is it always a case of go with the first version and iterate from there?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:22] <strong>Chris Huber:</strong> So it works the same exact way every time. The actual process does not use any AI at all. I used the AI to build it from the outside. But the actual, It&#8217;s literally like a machine. The process doesn&#8217;t use any AI to convert the website. We have some stuff in place, like when we&#8217;re using it on wordpress.com. We&#8217;re doing migrations from non WordPress to WordPress sites, we do it for assisted migrations currently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the people running these migrations will use the tool first and see how far it gets them. And then they take Claude Code or whatever and they work on the site that came out. And they hand it over to the customer. So it gets them closer to the finish line than they would have gotten if they just had to start building the site from scratch on their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then over time we&#8217;re getting closer to the finish line, and hopefully get to the point where we can just hand people the website coming from another source and be like, here&#8217;s your exact copy of your website WordPress version. And eventually we will make that like a publicly available thing. But that&#8217;s how we&#8217;re working on it internally, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:21] <strong>Nathan Wrigley:</strong> So I think I&#8217;d misunderstood there, so the AI portion is in the creation of the tool, but the tool itself is deterministic. The tool will give predictably the exact same thing out. If you give it the URL, it&#8217;s going to parse it with a mechanised approach? It&#8217;s not relying on AI at that point. And so do it once.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then it sounded to me from the way you described it, you were holding your hands up at this point. It sounded like your had two screens open. You&#8217;ve got the output and then maybe the original. And you&#8217;re trying to iterate and just spot the errors. Okay, let&#8217;s scroll them both and see. Ah look, that&#8217;s gone a bit astray there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then presumably at this point you&#8217;re logging into WordPress. If it can be done inside the block editor, you&#8217;re doing it there. But it also sounded like you are now at .com. You are removing that part even and just doing a second run with AI at that point. Rather than logging into WordPress and using the block editor, it&#8217;s more CLI. Let&#8217;s just see if the AI can spot those mistakes, because I spotted them, prompt it and fix it in that way. That&#8217;s interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:21] <strong>Chris Huber:</strong> So I&#8217;m the one just building the tool. There&#8217;s other people working on delivering websites to customers and stuff internally. But, I started looking at the websites originally, but now I have a, I just have a prompt that I copy and paste to the AI every time and it walks through the process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And what it does is it loads both sites in a headless browser called Playwright. Basically, I have the AI look at the site as if it was the site owner. I say you&#8217;re a non-technical site owner. Open this site and look at the Gutenberg editor and see how you would feel if you came over from Wix and this was what you got.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;ll go through and click things around in the editor and be like, okay, here&#8217;s my feedback. And then I say, okay, fix everything all at once and open pull requests. And it will fan out subagents, 10 or so at a time sometimes, and open pull requests in three repos, and then I just merge them and run it again. Because the automated releases that I mentioned.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s very much trusting the machine and letting them. The machine in this case is, more able to parse this than, than a human is because it&#8217;s so much at once. And just letting them do it is what I&#8217;ve found. Describing to them what I want them to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:26] <strong>Nathan Wrigley:</strong> I&#8217;m guessing the onboarding team over on .com, presumably, if you roll the clock back a couple of years, this was all a very manual process. Find a client, get them to sign on the dotted line. Okay, they&#8217;ve got a.com account, now they want to move over. And then it would&#8217;ve been a process of, okay, let&#8217;s inspect the site, let&#8217;s get a bunch of technical people on it, and figure out what we need to migrate and when, and try to map it. Get a designer in and recreate graphics, and colour palettes, and brands and all of this kind of stuff. But it sounds like these people no longer have a, place because you just use the tool and in most cases it&#8217;s going to work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Has that in fact been the case? It sounded like over on the .com side of things, there&#8217;s like this, I don&#8217;t know, 90, 95, 99%, trust in the tool now. That must be incredible. Presumably you can onboard people much more rapidly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:14] <strong>Chris Huber:</strong> Yeah, it&#8217;s not quite that much of trust in the tool yet. It&#8217;s more one in 10 sites are getting close enough to the finish line to just be handed off. So like the original process that you mentioned is a good process for like a big site, like manual migrations and stuff. But for small sites it&#8217;s not really a good business model. It&#8217;s not economically viable to spend a lot of resources rebuilding a small website because you&#8217;re putting a lot of manual effort into one website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So what we would do mostly in the past would be, if the customer is willing to do the do it for me route, where they have our team build it for them, we would do that. But otherwise we would offer them a content import. So they can just import all their blog posts or whatever, and then rebuild the site their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This kind of gives us an option for people that were historically told no, that we can now start saying yes to them. And letting them migrate over. It&#8217;s not necessarily about reducing the labour that was going into it because it was a dead end before, and now it&#8217;s not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:10] <strong>Nathan Wrigley:</strong> And how has it been received over on the .com side of things? I&#8217;m presuming that you are in touch with these people. And even if it&#8217;s a one in 10 at the moment, we have expectations that it&#8217;ll be two in 10, and then three in 10, and by the end of next year, maybe nine in 10 or what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That gives them the opportunity to talk about other things with the clients that they&#8217;re onboarding, I suspect. Instead of just, okay, let&#8217;s figure out how to make the exact same website that we had over there, over here. That doesn&#8217;t feel like necessarily interesting work anyway.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:36] <strong>Chris Huber:</strong> Yeah, exactly. But it was always really hard to make the exact copy. And yeah, the tool has a lot of internal support and a lot of internal attention. People are rallying behind it. It&#8217;s basically what I&#8217;ve been working on full time since WordCamp US. Three months ago now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I&#8217;ve been putting full-time effort into this tool for three months now. And now it&#8217;s starting. We have a lot of momentum behind it internally now that it&#8217;s starting to get to a point where it&#8217;s actually good. It&#8217;s very cool to see this for myself. I&#8217;m very proud of the work that we&#8217;ve done. And it&#8217;s exciting. It&#8217;s just exciting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:06] <strong>Nathan Wrigley:</strong> We mentioned that there were some things that it didn&#8217;t do particularly well. Presumably it would be nice to be able to hoover up some of that in the future. What would be the roadmap items that you&#8217;ve got for the next, I don&#8217;t know, short period of time, month, two months, six months, whatever it may be. What are the bits that it can&#8217;t currently do, or the bits that there&#8217;s wrinkles in, that you could tell us about that hopefully, given the passage of time, will go away?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:30] <strong>Chris Huber:</strong> The more complicated stuff is like, installing another plugin when you&#8217;re materialising the website. So the the most obvious example is WooCommerce. If we&#8217;re detecting products in the source, we actually pre-install WooCommerce, and convert to WooCommerce blocks, and import actual products into the catalogue, and like wire up everything that we possibly can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:50] <strong>Nathan Wrigley:</strong> That&#8217;s amazing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:51] <strong>Chris Huber:</strong> It&#8217;s crazy, but it doesn&#8217;t work very well yet, because it&#8217;s very complicated. But, another thing is like is like events. Like an events calendar on a website, the tool kind of chokes on that, but it&#8217;s the same process. You install The Events Calendar plugin. You find the most widely supported and used WordPress equivalent of whatever feature you need, and you find a way to deterministically wire it up on the back end.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There is a WordPress equivalent for like most things. It&#8217;s just a one at a time process to pick the one that, at least for .com. The tool itself is composable. So any developer. For forms, we use Jetpack Forms. But any developer can hook in and do whatever form provider they want, if they provide their own mappings to the tool. That&#8217;s the kind of stuff that doesn&#8217;t work quite as well right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, of course JavaScript animations and other things. WordPress has the Interactivity, API, so we do use that. More and more core blocks are coming in. Like we have the tabs now in the accordions and things like that, that we can actually represent in Gutenberg more effectively now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The real solution is just keep importing sites, you find that the tool used to choke on, it doesn&#8217;t choke on anymore, and you get further. And you just keep getting further and closer to success. The only thing it chokes on, this site is the products. Okay, so we&#8217;ll just work on improving the WooCommerce integration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah. So it&#8217;s like almost as far as you can get and then just keep. I like to think of it as raising the floor, like raising the bar is like. This is as bad as it could possibly be, and then the next time it&#8217;s a little bit better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:18] <strong>Nathan Wrigley:</strong> And it sounds like it&#8217;s going through those iterations fairly rapidly in terms of time, what three or four years ago would&#8217;ve been years into the future now increasingly feels like months, and then weeks, and then finally in a few years time, maybe days. A lot of this stuff will be taken on in short measure, things like an events system, or a WooCommerce system or an LMS kind of system. Maybe that stuff will be in scope in the near future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The project, obviously being on GitHub, and being a WordPressy thing is open source and I&#8217;m, just curious whether or not you are doing this hand in hand with any other people? Or is it just a project within Automattic? Or are you getting kind of intuitions from WordPress agencies out there who are obviously having to do this kind of work?</p>\n\n\n\n<p class=\"wp-block-paragraph\">They&#8217;re bringing in clients from all over the place and trying to convert them over to WordPress. I just wondered if there was any collaboration going on, or do you wish there to be collaboration?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:12] <strong>Chris Huber:</strong> I think something like this should be part of WordPress Core. I don&#8217;t know that necessarily this exact tool or this approach. There&#8217;s a lot of work in the ecosystem around this area, like Human Made has a tool like this. And then Pascal from WordPress Core, is working on this in Gutenberg, not the exact same thing, but some way to convert HTML to blocks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I just think it&#8217;s a big challenge for the WordPress ecosystem that if it gets solved can help move the whole project forward and help make us more future proof. Just because AI is so good at generating HTML, and that&#8217;s what kind of becoming the native format of the internet now. Maybe always has been, but just making that translatable into WordPress is something important I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:53] <strong>Nathan Wrigley:</strong> Yeah, I think so. And obviously in an era where market share in the WordPress space is no longer seemingly guaranteed to just keep climbing. People face with that decision of, okay, I&#8217;ve got a website, it&#8217;s now starting to look a bit stale, but rather than throw the baby out with a bath water, we&#8217;ll, okay, we want an alternative CMS. We want to upgrade, see where we can go. It feels like a tool like this makes WordPress a bit of a forerunner, actually.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re going to pick a CMS, have a CMS where there&#8217;s a pretty good chance that by clicking a button you can bring most of your existing stuff across. I don&#8217;t know what the other CMSs do in that regard. Maybe they do nothing, but this does feel like a tool in WordPress&#8217;s arsenal, which is pretty compelling. I would hope that it would bring a lot of people in our direction.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:42] <strong>Chris Huber:</strong> I hope so too, and I agree. I think the fact that it can exist. It takes one of the points of WordPress that has been difficult for people to embrace, which is the block editor. And it almost turns it into an advantage. Because then you get a WYSIWYG version of every website. Whereas if you were to generate a static site with AI and go and host it on a static host, you don&#8217;t have the CMS. If you want to add another blog post, you have to generate the page, upload it to the site. And of course there are solutions to this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What if you just want to change one word? You just want to go into the block editor and change the one word. Then you can do that and like without having to build the whole page from scratch in the editor. You have to be good at it and know what you&#8217;re doing to build a custom website using the block editor, I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:26] <strong>Nathan Wrigley:</strong> This is going to be a discussion which will go on, I think in the days, weeks, and months to come. Obviously everybody at the minute is very beguiled by the interface of building a website through some kind of chat mechanism. It&#8217;s so fascinating that&#8217;s possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then the reality of maintaining that, and understanding how that page even got there. And where do the assets, on that page even live? And how do I modify the title of the hero section over here? All of that has yet to land with ordinary people. Again, doing air quotes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:04] <strong>Chris Huber:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:05] <strong>Nathan Wrigley:</strong> If you&#8217;re very technical, you can probably figure all that stuff out, because you were probably the person that created that AI based site anyway. But if you&#8217;re not technical and your job is just to occasionally modify content, or inspect somebody else&#8217;s content, and click publish when it met the guidelines that you&#8217;d got as an organisation. You&#8217;re not going to care about some sort of CLI interface or getting an AI to do that for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You just want to be in, out, and then move on, because WordPress is not what makes up the majority of your day. I think all of that stuff is going to hit us in 2027, and it&#8217;ll be interesting to see where we land and where the landscape moves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:41] <strong>Chris Huber:</strong> Yeah, I hope that we can continue to grow WordPress definitely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:45] <strong>Nathan Wrigley:</strong> Okay, that&#8217;s really interesting. I&#8217;ll read into the record one more time the tool itself. So github.com/auttomatic, two ts, /static-site-importer. You can go over there and make comments. It&#8217;s a GitHub page so you can do all of that normal stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If people wanted to find you, Chris, do you hang out online anywhere? If people wanted to contact you and had intuitions on where this should perhaps go in the future?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:11] <strong>Chris Huber:</strong> Yeah, they can reach out to me on x x.com/chubes4, C-H-U-B-E-S four. They can also find my GitHub, which is the same tag. I have my personal WordPress site at extrachill.com, is like my main site. Then I have my other one, chubes.net. Or, just leave a pull request or a GitHub issue, me or my AI agent will reply.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:33] <strong>Nathan Wrigley:</strong> This is how it is in the year 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:35] <strong>Chris Huber:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:37] <strong>Nathan Wrigley:</strong> Okay Chris, absolutely fascinating. Let&#8217;s hope that the tool manages to do a lot more than you&#8217;ve described. It sounds like you&#8217;ve got a very extensive, and interesting, roadmap going on, but thank you for bringing that to us and, thank for explaining it all to us today. Appreciate it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:49] <strong>Chris Huber:</strong> Yeah. Thanks for your time. Thanks for having me.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://profiles.wordpress.org/extrachill/\">Chris Huber</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris’s journey with WordPress began back in his college days, first as a writer and blogger and eventually progressing to software engineering. After moving his personal site, extrachill.com, to WordPress in 2018, Chris went deeply into WordPress, developing custom plugins and exploring all the corners of the platform. His passion for experimentation and creative tech led him to Automattic, where he now helps shape the WordPress experience as a software engineer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our discussion centers around two main topics: Data Liberation and the Static Site Importer tool. We focused upon the evolving landscape of website migration and ownership. Chris explains how Data Liberation aims to make it easier for users to take control of their site, whether they&#8217;re moving to WordPress from platforms like Wix, Squarespace, or Drupal, or just want portability for their data.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into the Static Site Importer, which takes this a step further by converting any static HTML / CSS website into a fully editable WordPress block theme, headers, footers, and all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris walks us through how these tools work in tandem, highlighting the mechanics behind website crawling, mapping HTML elements to Gutenberg blocks, and handling complex features like WooCommerce and calendars.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the continuous improvement of these tools, how each migration helps raise the bar for future imports, and how this project could fundamentally change the way people move websites between platforms.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re curious about the future of website migration and how WordPress is removing the hurdles for users who want to truly own and manage their content, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Chris&#8217; <a href=\"https://extrachill.com\">extrachill.com</a> website</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris&#8217; <a href=\"https://chubes.net\">chubes.net</a> website</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/automattic/static-site-importer\">Static Site Importer</a> on GitHub</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.wordpress.com/studio/\">WordPress Studio</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/data-liberation/\">Data Liberation Project</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://liberate.sh\">liberate.sh</a> website</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://x.com/chubes4\">Chris on X</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:42;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:41:\"Donncha: Switching off PHP until upgraded\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89593199\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://odd.blog/2026/10/21/switching-off-php-until-upgraded/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:635:\"<p class=\"wp-block-paragraph\">There&#8217;s going to be an <a href=\"https://www.php.net/archive/2026.php#2026-10-20-1\">emergency PHP release</a> made in just over 2 hours. It&#8217;s to address a critical security bug. </p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m not sure how long it&#8217;ll be before Ubuntu updates, but I will preload a bunch of posts here and on inphotos.org using WP Super Cache and turn off PHP until it&#8217;s updated. The files will be served by Apache&#8217;s mod_rewrite, so no PHP involved at all. Uncached pages won&#8217;t be so lucky, but at least some pages will still be live.</p>\n\n#PHP #WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 11:46:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:43;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"WordPress.org blog: WordPress 7.2 Beta 1 is Ready for Download and Testing\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21813\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:17084:\"<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 1 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta1.zip\">Beta 1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-beta1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/?php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.2 Beta 1 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Editing Experience</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Responsive Design Controls</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Building on the responsive design improvements introduced in WordPress 7.1, WordPress 7.2 expands viewport-specific styling to additional design tools and blocks. Creators gain more granular control over how layouts and visual settings adapt across screen sizes, including responsive Gallery settings for columns, image cropping, and aspect ratios.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/80388\">GitHub #80388</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82003\">#82003</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Improved Global Styles and Design Tools</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21825\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 makes site-wide styling easier to manage with a new <em>Customized</em> filter for finding blocks with modified styles and inherited Global Styles values displayed directly in block inspector controls. Expanded design tools and support for styling form elements provide additional flexibility when creating a consistent visual identity across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/82520\">GitHub #82520</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/76525\">#76525</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/34198\">#34198</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84657\">#84657</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Text Shadow Support</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces new text shadow controls, giving creators more ways to add depth and emphasis to their content. Text shadows can be customized through block settings and defined as presets in <code>theme.json</code>, making it easier to maintain consistent typography across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/73320\">GitHub #73320</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79584\">GitHub #79584</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">Trac #65869</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Easier Navigation Management</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Improvements to the Site Editor make managing navigation links more intuitive. Creators can add, organize, and edit navigation items directly from the editor sidebar, making it easier to maintain site menus without interrupting their editing workflow.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/77069\">GitHub #77069</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Better Collaboration with Notes</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21820\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces Emoji reactions on notes and a new toolbar icon that makes Notes easier to access and manage. Notes move to the editor canvas, bringing conversations directly into the margin. Users can now keep Notes and the block settings sidebar open simultaneously, making it easier to review feedback while editing content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A new minimized Notes mode reduces visual clutter, while improvements to positioning and display create a smoother, more consistent collaboration experience.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/79970\">GitHub #79970</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83786\">GitHub #83786</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/80015\">GitHub #80015</a>, <a href=\"https://core.trac.wordpress.org/ticket/64638\">Trac #64638</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster, More Efficient Media Uploads</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands client-side media processing to the Media Library, allowing images to be resized, compressed, and converted directly in the browser before being uploaded. This can improve upload performance, reduce server resource usage, and provide better support for modern image formats, particularly on hosting environments with limited image-processing capabilities.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65661\">Trac #65661</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/12585\">GitHub #12585</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">New “On This Day” Dashboard Widget</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a new <strong>On This Day</strong> dashboard widget that helps users rediscover content published on the same date in previous years. By highlighting posts from the site&#8217;s history, the widget makes it easier to revisit past content, celebrate milestones, and find opportunities to refresh or reshare older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65116\">Trac #65116</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Block Editor Usability Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 includes a collection of smaller improvements aimed at reducing friction in everyday editing. These changes include clearer error messages, more helpful feedback when something goes wrong, and refinements to common editor interactions, making the editing experience more predictable and approachable.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21821\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/81453\">GitHub #81453</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82496\">#82496</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84656\">#84656</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84649\">#84649</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">A More Consistent WordPress Admin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 continues modernizing the administration experience by replacing legacy Dashicons in the admin bar and sidebar with icons from the WordPress icon library. The updated icons bring greater visual consistency between the traditional WordPress dashboard and newer editing interfaces.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/wordpress-develop/pull/12270\">GitHub #12270</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">An Updated Block Settings Experience</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21822\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A new DataForm-powered inspector introduces a refreshed approach to managing block settings in the editor. Built on the DataForm component system, this work aims to provide more consistent controls and a more extensible foundation for future block editing improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg\">GitHub Gutenberg</a> · <a href=\"https://make.wordpress.org/core/2026/09/17/call-for-testing-dataform-editor-inspector/\">Call for Testing</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster WordPress Administration</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 improves admin performance by modernizing how scripts and stylesheets are loaded. Instead of combining assets into large files, WordPress now loads them individually for better browser caching. A new prefetching mechanism also anticipates which admin screen users are likely to visit next, loading its resources in advance to make navigation between the dashboard, post lists, and editor faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/57548\">Trac #57548</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">For Developers</h2>\n\n\n\n<h3 class=\"wp-block-heading\">New Secrets API</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a <strong>Secrets API</strong>, providing developers with a standardized, secure way to store sensitive credentials such as API keys and authentication tokens. The API supports encryption at rest, credential rotation, and customizable storage providers, helping plugins and integrations manage sensitive information more securely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://core.trac.wordpress.org/ticket/66187\">Learn more (Trac #66187)</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Random Content Redirects</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 adds support for random content redirects, allowing visitors to discover a randomly selected post through a dedicated URL. This provides a simple way to encourage content exploration and help readers rediscover older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/64498\">Trac #64498</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">More Powerful APIs for Developers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands the <strong>Abilities API</strong> with new capabilities for accessing and querying WordPress data, providing a more consistent foundation for integrations, automation, and AI-powered tools. (<a href=\"https://core.trac.wordpress.org/ticket/66268\">Trac #66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/64605\">#64605</a>, <a href=\"https://core.trac.wordpress.org/ticket/64657\">#64657</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Enhancements to the <strong>Interactivity API</strong> introduce new ways to render trusted HTML and manage reactive navigation, giving developers more flexibility when building dynamic, interactive blocks. (<a href=\"https://core.trac.wordpress.org/ticket/66246\">Trac #66246</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83092\">Gutenberg PR #83092</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional improvements to the <strong>HTML API</strong>, block supports, and responsive design tools provide more reliable markup processing and greater control over how custom blocks are styled and displayed across devices. (<a href=\"https://core.trac.wordpress.org/ticket/65824\">Trac #65824</a>, <a href=\"https://core.trac.wordpress.org/ticket/66150\">#66150</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">#65869</a>)</p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the<a href=\"https://make.wordpress.org/test/\"> testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 will include new features that were previously only available in the Gutenberg plugin. Learn more about Gutenberg updates since WordPress 7.1 in the <a href=\"https://make.wordpress.org/core/tag/gutenberg-new/\">What’s New in Gutenberg</a> posts for versions <a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">23.7</a>, <a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">23.8</a>, <a href=\"https://make.wordpress.org/core/2026/09/02/whats-new-in-gutenberg-23-9-2-september/\">23.9</a>, <a href=\"https://make.wordpress.org/core/2026/09/16/whats-new-in-gutenberg-24-0-16-september/\">24.0</a>, <a href=\"https://make.wordpress.org/core/2026/09/30/whats-new-in-gutenberg-24-1-30-september/\">24.1</a>, <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\">24.2</a>, and 24.3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What’s new in WordPress 7.2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">With so much in progress for WordPress 7.2 Beta 1, this is still only the beginning; expect continued refinement with each Beta and RC release ahead of the final release on <strong>December 8, 2026</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Just for you: a Beta 1 haiku:</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Ipsum takes the stage<br />Secrets bloom, designs take shape<br />New blocks come alive</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to </em><a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/annezazu/\"><span class=\"mentions-prefix\">@</span>annezazu</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/adamsilverstein/\"><span class=\"mentions-prefix\">@</span>adamsilverstein</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/westonruter/\"><span class=\"mentions-prefix\">@</span>westonruter</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/markoserb/\"><span class=\"mentions-prefix\">@</span>markoserb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/im3dabasia1/\"><span class=\"mentions-prefix\">@</span>im3dabasia1</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/jorbin/\"><span class=\"mentions-prefix\">@</span>jorbin</a>, and <a class=\"mention\" href=\"https://profiles.wordpress.org/noruzzaman/\"><span class=\"mentions-prefix\">@</span>noruzzaman</a><em> for proofreading and review.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 16:02:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:44;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"Open Channels FM: Community Without the Noise, Revisited\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564390\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"https://openchannels.fm/community-without-the-noise-revisited/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"A commentary on building meaningful online communities that prioritize value and listening over constant activity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 13:46:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:45;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"OpenStation Blog: OpenStation: turn wp-admin into a desktop, and try it in 30 seconds\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1495\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:102:\"https://openstation.blog/2026/10/20/openstation-turn-wp-admin-into-a-desktop-and-try-it-in-30-seconds/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2722:\"<p class=\"wp-block-paragraph\">OpenStation is a free WordPress plugin that turns wp-admin into a desktop. Every admin screen opens in its own window that you can move, resize and keep open next to the others. You can try it in your browser right now, with nothing to install.</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Can&#8217;t see the video? <a href=\"https://www.youtube.com/watch?v=g5MLB3WMlCc\">Watch it on YouTube</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why we built it</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Most of us spend the day jumping between screens in wp-admin. You open a post, go back to the list, check the media library, then go back again. With OpenStation, those screens stay open side by side, so you don&#8217;t lose your place.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What you get</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A window for every admin page: posts, media, settings, plugins</li>\n\n\n\n<li>A dock with your whole admin menu, including your other plugins</li>\n\n\n\n<li>Several desktops, for example one for writing and one for site settings</li>\n\n\n\n<li>Wallpapers, widgets and accent colors</li>\n\n\n\n<li>Cmd+K to jump anywhere fast</li>\n\n\n\n<li>Your windows are still open when you come back</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Try it in your browser</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Go to the <a href=\"https://wordpress.org/plugins/desktop-mode/\">OpenStation page on WordPress.org</a> and click <strong>Live Preview</strong>. It runs a full WordPress site with OpenStation in your browser tab, so you can&#8217;t break anything.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Install it on your site</h2>\n\n\n\n<ol class=\"wp-block-list\">\n<li>In your admin, go to Plugins → Add New and search for &#8220;OpenStation&#8221;</li>\n\n\n\n<li>Click Install Now, then Activate</li>\n\n\n\n<li>Click the desktop icon in the top-right corner of the admin bar</li>\n</ol>\n\n\n\n<h2 class=\"wp-block-heading\">It&#8217;s safe to try</h2>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation is opt-in for each user, so the rest of your team keeps the normal admin. Click the same icon to go back to the classic view. If you deactivate the plugin, wp-admin goes back to exactly how it was. It doesn&#8217;t change WordPress core.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Tell us what you think</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Have a question? Ask in the <a href=\"https://wordpress.org/support/plugin/desktop-mode/\">support forum</a>. Found a bug or have an idea? <a href=\"https://github.com/WordPress/openstation/issues\">Open an issue on GitHub</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 13:44:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:46;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"Open Channels FM: More Code, More Problems? What AI-Generated Software Means for Us\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563871\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://openchannels.fm/more-code-more-problems-what-ai-generated-software-means-for-us/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:327:\"AI tools have simplified app creation, enabling rapid prototyping. However, the challenge now lies in discerning which ideas are genuinely valuable to users. As anyone can create apps quickly, the focus should shift from mere production to understanding user needs and ensuring the apps solve real problems to avoid mediocrity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 10:01:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:47;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:41:\"Donncha: Travel Steps is a travel journal\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89593168\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://odd.blog/2026/10/19/travel-steps-is-a-travel-journal/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:10115:\"<p class=\"wp-block-paragraph\">I made a WordPress plugin for my holidays. It&#8217;s called <a href=\"https://wordpress.org/plugins/travel-steps-storyteller/\">Travel Steps Storyteller</a>, and it turns a trip into a page with a map down one side and the story of each day down the other.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593171 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/01-trip-header.avif\" width=\"2000\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Every photo I take ends up in <a href=\"https://immich.app\">Immich</a>, on my own server. My phone sends where I&#8217;ve been to <a href=\"https://dawarich.app\">Dawarich</a>, on the same server. So after a trip I have all the photos and the whole route, sitting in two apps on my private server. The travel apps that make nice trip pages want your photos and your location on their servers. I&#8217;d rather keep them on mine.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How it works</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You make a trip, give it a first and last day, and press Sync. Travel Steps asks Dawarich for your location over those days, and Immich for the photos you took. You can pick one Immich album instead. If you don&#8217;t use Immich at all, upload the photos to the trip. It will detect the start and end dates from the uploaded photos, or an Immich album too.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593182 not-transparent\" height=\"1480\" src=\"https://odd.blog/files/2026/10/08-sync-and-steps.avif\" width=\"1520\" /><figcaption class=\"wp-element-caption\">One sync, and a step for each day.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Sync makes a draft post for every day that has favourite photos. Each one is a &#8220;step&#8221;. It splits the day into places too. A new place starts when a favourite is more than 2 km from the last one and in a different town. Each place gets a heading and a block of photos, so all that&#8217;s left is the writing.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593175 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/09-block-editor.avif\" width=\"2000\" /><figcaption class=\"wp-element-caption\">Each day is a post you write in the block editor. The photos under each heading come straight from Immich.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Place names come from <a href=\"https://www.geonames.org\">GeoNames</a> data that ships with the plugin, so naming a town doesn&#8217;t send your location anywhere. Immich only names a place from a photo&#8217;s own GPS. A photo from a camera without GPS gets placed from your Dawarich history instead, and named the same way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Publish the days you want people to see. Drafts stay private, and so do their photos.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593174 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/02-map-timeline.avif\" width=\"2000\" /><figcaption class=\"wp-element-caption\">The map follows you as you scroll. Get to day 3 and day 3&#8217;s markers light up.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The distance at the top follows the whole route, flights included. GPS glitches that put you in the Atlantic for a second are dropped. Anything you&#8217;d have needed to travel faster than 1,080 km/h to reach counts as a glitch. Sorry, Concorde.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Your photos stay at home</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Visitors never talk to Immich. WordPress fetches each photo, caches it and serves it itself, so Immich and the original files stay private. It caches a trip&#8217;s photos in the background after a sync. The trip keeps working when Immich is down. A daily sweep deletes cached photos older than a number of days you choose, whether a trip still uses them or not, and they&#8217;re fetched again the next time someone looks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Photos you upload to a trip keep their GPS in the original, but it&#8217;s stripped from every copy WordPress makes, and only those copies are ever sent. A trip can have a password, and you can let some logged-in people skip it.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Pin, hide, cover</h2>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593176 not-transparent\" height=\"1060\" src=\"https://odd.blog/files/2026/10/03-photo-tools.avif\" width=\"1300\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Hover over a photo to pin it (always show it), hide it, or make it the trip&#8217;s cover. The rest of the day&#8217;s photos sit behind a &#8220;Show more photos&#8221; link.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On phones, those buttons show up after you press Edit photos as illustrated by the images below.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593177 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/04-phone-trip.avif\" width=\"924\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593178 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/05-phone-edit-photos.avif\" width=\"924\" /></figure>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Tap a photo and it opens full screen. On a phone you swipe from one photo to the next, edge to edge. On a desktop there are arrows, and the arrow keys work too.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593185 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/07-phone-lightbox.avif\" width=\"924\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593179 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/06-phone-lightbox-swipe.avif\" width=\"924\" /></figure>\n</div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Try it</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Here&#8217;s a <a href=\"https://playground.wordpress.net/?blueprint-url=https://raw.githubusercontent.com/donnchawp/travel-steps/master/demo/blueprint.json\">demo in WordPress Playground</a>. It&#8217;s a week in the west of Ireland, running in your browser that installs nothing. Stand-in Immich and Dawarich servers feed the real sync code with photos from Unsplash. You&#8217;re logged in as an admin, so press Sync, pin and hide photos, and edit the days in the block editor. It all disappears when you close the tab.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The code is <a href=\"https://github.com/donnchawp/travel-steps\">on GitHub</a> and you can install it from the WordPress plugin repo <a href=\"https://wordpress.org/plugins/travel-steps-storyteller/\">here</a>. To install it, look for &#8220;Travel Steps Storyteller&#8221; in the plugins page. It needs WordPress 6.7 and PHP 8.0. Immich and Dawarich are both optional. It has been submitted to WordPress.org but if you read this blog, you&#8217;ll know how to install a plugin from a zip file!</p>\n\n\n\n<h2 class=\"wp-block-heading\">WpApp</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Travel Steps is built on <a href=\"https://github.com/akirk/wp-app\">WpApp</a>, Alex Kirk&#8217;s framework for building apps on top of WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A plugin usually adds screens to wp-admin, or puts its pages inside your theme and hopes the CSS gets along. A WpApp app gets its own URLs instead (<code>/travel-steps/</code> here), and its pages are plain HTML with no theme in the way. WordPress still does the boring work: users and logins, roles, the block editor, the REST API, cron and the database. WpApp adds the bits in between:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>URL routing, using WordPress rewrite rules,</li>\n\n\n\n<li>pages that don&#8217;t load your theme,</li>\n\n\n\n<li>the admin bar on every page, with the app&#8217;s own icon (the green map at the top of my screenshots),</li>\n\n\n\n<li>access control using WordPress capabilities.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can start one with <code>composer create-project akirk/create-wp-app my-app</code>. Alex has a <a href=\"https://wpapps.kirk.at/\">showcase of apps built with it</a>, including a cookbook and a family wiki.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Built with Claude Code</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I wrote Travel Steps with <a href=\"https://claude.ai/code\">Claude Code</a>. The first commit was on 11 October, and there are many more now. Most of the work went round the same loop. I file an issue, Claude fixes it test-first on a branch and opens a pull request, and other agents review it. I deploy it to my own server and try it. The tests run in WordPress Playground too, the same as the demo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you run Immich, give it a whirl. Bug reports welcome on GitHub <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"has-small-font-size wp-block-paragraph\">Demo photos from <a href=\"https://unsplash.com\">Unsplash</a>: Cliffs of Moher by <a href=\"https://unsplash.com/photos/Zf9bvJ6182k\">Jarek Skowron</a>, Temple Bar by <a href=\"https://unsplash.com/photos/-ABmxr3Yo4Y\">Sarah</a>, Galway by Daniel Zbroja and Anna Hunko, Kilronan by Jonathan Borba. Map © <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors.</p>\n\n#TravelSteps #WordPress #WordPressplugin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 14:15:48 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:48;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"WordCamp Central: WordPress Campus Connect Ahmad Education, Dhaka 2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16498954\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"https://central.wordcamp.org/news/2026/10/wordpress-campus-connect-ahmad-education-dhaka-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4344:\"<div class=\"wp-block-columns has-black-background-color has-text-color has-background has-link-color has-small-font-size wp-elements-20 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\" style=\"color: #ffffff;\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading has-white-color has-text-color has-link-color wp-elements-21\">The Truly Meaning moment in this event</h3>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-22 wp-block-paragraph\">Campus Connect Event Successfully Completed!</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-23 wp-block-paragraph\">We are pleased to share that the Campus Connect<strong> </strong>event, held on Thursday, October 1st, was successfully completed with the participation of students from Ahmad’s Education.</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-24 wp-block-paragraph\">Ahmad’s Education has already collaborated with WordPress and successfully completed two batches. This event was another valuable opportunity to strengthen our collaboration, share knowledge, and inspire students to explore new learning opportunities.</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-25 wp-block-paragraph\">A heartfelt thanks to the WordPress team, the organizers, and all the students who contributed to making this event successful.<br />Looking forward to more collaborations and learning opportunities together!</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large is-style-default wp-duotone-unset-2\"><a href=\"https://central.wordcamp.org/files/2026/10/group2-scaled.jpg\"><img alt=\"\" class=\"wp-image-16499417\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/10/group2-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/ahmadsEducation-scaled.jpg\"><img alt=\"\" class=\"wp-image-16499418\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/10/ahmadsEducation-1024x768.jpg\" width=\"1024\" /></a></figure>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<div class=\"wp-block-columns are-vertically-aligned-center is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center has-white-background-color has-background is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/abdullah-noman.jpg\"><img alt=\"\" class=\"wp-image-16499419\" src=\"https://central.wordcamp.org/files/2026/10/abdullah-noman.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/aminul.jpg\"><img alt=\"\" class=\"wp-image-16499420\" src=\"https://central.wordcamp.org/files/2026/10/aminul.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/atikur-rahman-geting-certificate.jpg\"><img alt=\"\" class=\"wp-image-16499424\" height=\"1536\" src=\"https://central.wordcamp.org/files/2026/10/atikur-rahman-geting-certificate.jpg\" width=\"2048\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/guies-3.jpg\"><img alt=\"\" class=\"wp-image-16499423\" src=\"https://central.wordcamp.org/files/2026/10/guies-3.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/guist-1.jpg\"><img alt=\"\" class=\"wp-image-16499421\" src=\"https://central.wordcamp.org/files/2026/10/guist-1.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large is-style-default\"><a href=\"https://central.wordcamp.org/files/2026/10/guist-2.jpg\"><img alt=\"\" class=\"wp-image-16499422\" src=\"https://central.wordcamp.org/files/2026/10/guist-2.jpg\" /></a></figure>\n</figure>\n</div>\n</div>\n</div></div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 11:04:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"ATIKUR RAHMAN\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:49;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Why Fast AI Inference Is a Game Changer for Developers\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563865\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://openchannels.fm/why-fast-ai-inference-is-a-game-changer-for-developers/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:332:\"In tech, speed can make all the difference. One topic that doesn&#8217;t get enough attention is just how much faster AI inference is changing the way developers work. Training AI models still grabs the headlines with all the talk about big clusters and huge data sets, but the real impact for most developers happens when [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 09:48:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Tue, 10 Nov 2026 02:50:22 GMT\";s:12:\"content-type\";s:8:\"text/xml\";s:13:\"last-modified\";s:29:\"Tue, 10 Nov 2026 02:30:30 GMT\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:2:\"br\";s:7:\"alt-svc\";s:5:\"clear\";s:13:\"x-remembering\";s:58:\"Eric Binnion <https://friendsofericbinnion.wordpress.com/>\";s:4:\"x-nc\";s:9:\"HIT dca 2\";}s:5:\"build\";i:1760643936;s:21:\"cache_expiration_time\";i:1794322223;s:23:\"__cache_expiration_time\";i:1794322223;}','off');
